103	async function makeClaimDevnet(
104	  epoch: number,
105	  claim: ClaimStruct | null,
106	  outboxStateRoot: string,
107	  transactionHandler: IDevnetTransactionHandler,
108	  veaInbox: any,
109	  emitter: EventEmitter
110	): Promise<IDevnetTransactionHandler | null> {
111	  if (claim == null) {
112	    const [savedSnapshot] = await Promise.all([veaInbox.snapshots(epoch)]);
113	
114	    const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != ethers.ZeroHash;
115	    if (newMessagesToBridge && savedSnapshot != ethers.ZeroHash) {
116	      await transactionHandler.devnetAdvanceState(savedSnapshot);
117	      return transactionHandler;
118	    }
119	  }
120	  emitter.emit(BotEvents.NO_CLAIM_REQUIRED, epoch);
121	  return null;
122	}
