182	async function verifyClaim(
183	  transactionHandler: ITransactionHandler,
184	  claim: ClaimStruct,
185	  veaOutboxProvider: JsonRpcProvider
186	) {
187	  if (claim.honest == ClaimHonestState.CLAIMER) {
188	    await transactionHandler.withdrawClaimDeposit();
189	    return transactionHandler;
190	  } else if (claim.honest == ClaimHonestState.NONE) {
191	    const finalizedOutboxBlock = await veaOutboxProvider.getBlock("finalized");
192	    if (claim.challenger != ethers.ZeroAddress) {
193	      return transactionHandler;
194	    }
195	    if (claim.timestampVerification == 0) {
196	      await transactionHandler.startVerification(finalizedOutboxBlock.timestamp);
197	    } else {
198	      await transactionHandler.verifySnapshot(finalizedOutboxBlock.timestamp);
199	    }
200	    return transactionHandler;
201	  }
202	}
