30	export async function challengeAndResolveClaim({
31	  chainId,
32	  claim,
33	  epoch,
34	  epochPeriod,
35	  veaInbox,
36	  veaInboxProvider,
37	  veaOutboxProvider,
38	  veaOutbox,
39	  transactionHandler,
40	  emitter = defaultEmitter,
41	  veaRouterProvider,
42	  fetchClaimResolveState = getClaimResolveState,
43	  fetchBlocksAndCheckFinality = getBlocksAndCheckFinality,
44	  fetchSettledReadBlocks = resolveSettledReadBlocks,
45	  fetchTransactionHandler = getTransactionHandler,
46	}: ChallengeAndResolveClaimParams): Promise<ITransactionHandler | null> {
47	  if (!claim) {
48	    emitter.emit(BotEvents.NO_CLAIM, epoch);
49	    return null;
50	  }
51	  const l1Provider = veaRouterProvider ?? veaOutboxProvider;
52	  // Resolve the blocks this epoch can be read as settled at before reading
53	  // anything: a challenge stakes a deposit on the value we are about to read.
54	  // outboxProvider anchors Arbitrum's finality check (L1/router); outboxChainProvider
55	  // is the outbox's own chain, which differs from it on routed chains like arbToGnosis.
56	  const settledBlocks = await fetchSettledReadBlocks({
57	    inboxProvider: veaInboxProvider,
58	    outboxProvider: l1Provider,
59	    outboxChainProvider: veaOutboxProvider,
60	    epoch,
61	    epochPeriod,
62	    emitter,
63	    fetchBlocksAndCheckFinality,
64	  });
65	  if (!settledBlocks) return null;
66	  const ethBlockTag = "finalized";
67	
68	  if (!transactionHandler) {
69	    const TransactionHandler = fetchTransactionHandler(chainId, Network.TESTNET);
70	    transactionHandler = new TransactionHandler({
71	      chainId,
72	      network: Network.TESTNET, // Hardcoded as TESTNET & MAINNET have same contracts
73	      epoch,
74	      veaInbox,
75	      veaOutbox,
76	      veaInboxProvider,
77	      veaOutboxProvider,
78	      veaRouterProvider,
79	      emitter,
80	      claim,
81	    });
82	  } else {
83	    transactionHandler.claim = claim;
84	  }
85	  // If claim is already resolved, nothing to do
86	  if (claim.honest !== 0) {
87	    emitter.emit(BotEvents.CLAIM_ALREADY_RESOLVED, epoch);
88	    if (claim.honest === 2) {
89	      await transactionHandler.withdrawChallengeDeposit();
90	      return transactionHandler;
91	    }
92	    return null;
93	  }
94	
95	  const { challenged, toRelay } = await challengeAndCheckRelay({
96	    veaInbox,
97	    epoch,
98	    claim,
99	    transactionHandler,
100	    arbitrumBlockNumber: settledBlocks.inboxBlock,
101	  });
102	  if (!toRelay && !challenged) {
103	    return null;
104	  } else if (challenged && !toRelay) {
105	    return transactionHandler;
106	  }
107	  await handleResolveFlow({
108	    chainId,
109	    epoch,
110	    epochPeriod,
111	    claim,
112	    veaInbox,
113	    veaInboxProvider,
114	    veaOutbox,
115	    veaOutboxProvider,
116	    veaRouterProvider,
117	    ethBlockTag,
118	    transactionHandler,
119	    fetchClaimResolveState,
120	  });
121	
122	  return transactionHandler;
123	}
