125	interface ChallengeAndCheckRelayParams {
126	  veaInbox: any;
127	  epoch: number;
128	  claim: ClaimStruct;
129	  transactionHandler: ITransactionHandler;
130	  arbitrumBlockNumber: number;
131	}
132	async function challengeAndCheckRelay({
133	  veaInbox,
134	  epoch,
135	  claim,
136	  transactionHandler,
137	  arbitrumBlockNumber,
138	}: ChallengeAndCheckRelayParams): Promise<{ challenged: boolean; toRelay: boolean }> {
139	  const onChainSnapshot = await veaInbox.snapshots(epoch, { blockTag: arbitrumBlockNumber });
140	  const isNotChallenged = claim.challenger === ethers.ZeroAddress;
141	  const challengeAndRelayState = {
142	    challenged: false,
143	    toRelay: false,
144	  };
145	  if (onChainSnapshot !== claim.stateRoot && isNotChallenged) {
146	    await transactionHandler.challengeClaim();
147	    challengeAndRelayState.challenged = true;
148	  }
149	  if (!isNotChallenged) {
150	    return { challenged: true, toRelay: true };
151	  }
152	  return challengeAndRelayState;
153	}
