155	interface ResolveFlowParams {
156	  chainId: number;
157	  epoch: number;
158	  epochPeriod: number;
159	  claim: ClaimStruct;
160	  veaInbox: any;
161	  veaInboxProvider: JsonRpcProvider;
162	  veaOutbox: any;
163	  veaOutboxProvider: JsonRpcProvider;
164	  veaRouterProvider?: JsonRpcProvider;
165	  ethBlockTag: "latest" | "finalized";
166	  transactionHandler: ITransactionHandler;
167	  fetchClaimResolveState: typeof getClaimResolveState;
168	}
169	async function handleResolveFlow({
170	  chainId,
171	  epoch,
172	  epochPeriod,
173	  claim,
174	  veaInbox,
175	  veaInboxProvider,
176	  veaOutbox,
177	  veaOutboxProvider,
178	  veaRouterProvider,
179	  ethBlockTag,
180	  transactionHandler,
181	  fetchClaimResolveState,
182	}: ResolveFlowParams): Promise<void> {
183	  const claimResolveState = await fetchClaimResolveState({
184	    chainId,
185	    veaInbox,
186	    veaInboxProvider,
187	    veaOutbox,
188	    veaOutboxProvider,
189	    veaRouterProvider,
190	    epoch,
191	    epochPeriod,
192	    headBlockTag: ethBlockTag,
193	  });
194	
195	  if (!claimResolveState.sendSnapshot.status) {
196	    await transactionHandler.sendSnapshot();
197	    return;
198	  }
199	  const execStatus = claimResolveState.execution.status;
200	  if (execStatus === 1) {
201	    await transactionHandler.resolveChallengedClaim(claimResolveState.sendSnapshot.txHash);
202	  } else if (execStatus === 2 && claim.honest === 2) {
203	    await transactionHandler.withdrawChallengeDeposit();
204	  }
205	}
